import{_ as n,o as s,c as a,b as t}from"./app-892aa20c.js";const e={},p=t(`<blockquote><p>简介：拼手气类的游戏，更能激发用户购物和社交的趣味性，以及游戏竞争心理，拼手气类的活动甚至可以影响人们消费心理。拼手气红包就是最简单的例子。</p><p>顾名思义，二倍均值算法的核心思想是根据每次剩余的总金额M和剩余人数N，执行M/N再乘以2的操作得到一个边界值E，然后制定一个从0到E的随机区间，在这个随机区间内将产生一个随机金额R， 此时总金额M将更新为M-R，剩余人数N更新为N-1。再继续重复上述执行流程，以此类推，直至最终剩余人数N-1为0，即代表随机数已经产生完毕。</p></blockquote><h4 id="两种生成红包的方式对比" tabindex="-1"><a class="header-anchor" href="#两种生成红包的方式对比" aria-hidden="true">#</a> 两种生成红包的方式对比</h4><p>拼手气红包有两种计算方法，一种是预计算，一种是实时算。</p><p>预计算在生成拼手气红包的时候，会提前根据总金额M和红包人数N，生成每个红包的金额，在抢红包的过程中，只需要从金额列表中取出，直至取完。这种方式需要占用额外的存储空间并且增加额外的I/O，在高并发场景下并不是最优的解决方案。 实时算采用的是纯内存计算，不需要预算空间存储，实时性很高。</p><h4 id="预计算代码实现" tabindex="-1"><a class="header-anchor" href="#预计算代码实现" aria-hidden="true">#</a> 预计算代码实现</h4><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code>    <span class="token doc-comment comment">/**
     * 拆包
     *
     * <span class="token keyword">@param</span> <span class="token parameter">totalAmount</span> 总金额
     * <span class="token keyword">@param</span> <span class="token parameter">totalCount</span>  总数量
     * <span class="token keyword">@return</span> 拆包结果
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Integer</span><span class="token punctuation">&gt;</span></span> <span class="token function">divide</span><span class="token punctuation">(</span><span class="token keyword">int</span> totalAmount<span class="token punctuation">,</span> <span class="token keyword">int</span> totalCount<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span>totalAmount <span class="token operator">&lt;</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">IllegalArgumentException</span><span class="token punctuation">(</span><span class="token string">&quot;totalAmount cannot be less than the 0&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span>totalAmount <span class="token operator">&lt;</span> totalCount<span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">IllegalArgumentException</span><span class="token punctuation">(</span><span class="token string">&quot;totalAmount cannot be less than the totalCount&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Integer</span><span class="token punctuation">&gt;</span></span> result <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ArrayList</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">Random</span> random <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Random</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token comment">// 剩余金额</span>
        <span class="token keyword">int</span> remainingAmount <span class="token operator">=</span> totalAmount<span class="token punctuation">;</span>
        <span class="token comment">// 剩余数量</span>
        <span class="token keyword">int</span> remainingCount <span class="token operator">=</span> totalCount<span class="token punctuation">;</span>
        <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">int</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> totalCount <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token comment">// 本红包的最大值 人数 / 金额 * 2</span>
            <span class="token keyword">int</span> max <span class="token operator">=</span> <span class="token number">2</span> <span class="token operator">*</span> <span class="token punctuation">(</span>remainingAmount <span class="token operator">/</span> remainingCount<span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token comment">// 随机生成一个 1 到 max 之间的金额</span>
            <span class="token keyword">int</span> amount <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">+</span> random<span class="token punctuation">.</span><span class="token function">nextInt</span><span class="token punctuation">(</span>max <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token comment">// 更新剩余金额与人数</span>
            remainingCount<span class="token operator">--</span><span class="token punctuation">;</span>
            remainingAmount <span class="token operator">=</span> remainingAmount <span class="token operator">-</span> amount<span class="token punctuation">;</span>

            result<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>amount<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token comment">// 添加最后剩余的金额</span>
        result<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>remainingAmount<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">return</span> result<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,6),o=[p];function c(l,i){return s(),a("div",null,o)}const r=n(e,[["render",c],["__file","pinshouqihongbaogongnenshixian.html.vue"]]);export{r as default};
